bash -lc "cat > agent-graph-demo/app/page.tsx <<'PAGE'
'use client';
import React from 'react';
import ReactFlow, { Background, Controls, MiniMap } from 'reactflow';
import 'reactflow/dist/style.css';

const nodes = [
  { id: '1', position: { x: 0, y: 0 }, data: { label: 'Agent' } },
  { id: '2', position: { x: 200, y: 100 }, data: { label: 'Tool' } },
  { id: '3', position: { x: 0, y: 200 }, data: { label: 'Memory' } }
];
const edges = [
  { id: 'e1-2', source: '1', target: '2' },
  { id: 'e1-3', source: '1', target: '3' }
];

export default function Home() {
  return (
    <main className="min-h-screen bg-white text-zinc-900">
      <div className="mx-auto max-w-5xl px-6 py-10">
        <h1 className="text-4xl font-semibold">Agent Graph Demo</h1>
        <p className="mt-2 text-zinc-600">React Flow + LangGraph/LangChain dependencies ready.</p>
        <div className="mt-6 h-[520px] rounded-xl border border-zinc-200">
          <ReactFlow nodes={nodes} edges={edges} fitView>
            <MiniMap />
            <Controls />
            <Background />
          </ReactFlow>
        </div>
      </div>
    </main>
  );
}
PAGE"

bash -lc "cat > agentkit-stack/prisma/schema.prisma <<'PRISMA'
datasource db {
  provider = \"postgresql\"
  url      = env(\"DATABASE_URL\")
}

generator client {
  provider = \"prisma-client-js\"
}

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  name      String?
  createdAt DateTime @default(now())
}
PRISMA"

bash -lc "cat > agentkit-stack/app/api/auth/[...nextauth]/route.ts <<'AUTH'
import NextAuth from \"next-auth\";
import Credentials from \"next-auth/providers/credentials\";

const handler = NextAuth({
  providers: [
    Credentials({
      name: \"Credentials\",
      credentials: { email: { label: \"Email\", type: \"email\" } },
      async authorize(credentials) {
        if (!credentials?.email) return null;
        return { id: credentials.email, email: credentials.email };
      }
    })
  ],
  session: { strategy: \"jwt\" }
});

export { handler as GET, handler as POST };
AUTH"

